INSERT INTO dsl_rolling_diag_c26c5c6a0208.tail_1 SELECT mktcode,tgtcode,bizdate,closePrice FROM (SELECT b.mktcode,b.tgtcode,b.bizdate,b.closePrice,ROW_NUMBER() OVER(PARTITION BY b.mktcode,b.tgtcode ORDER BY b.bizdate DESC) AS rn FROM (SELECT mktcode,tgtcode,bizdate,closePrice FROM dsl_rolling_diag_c26c5c6a0208.tail_0 UNION ALL SELECT b.mktcode,b.tgtcode,b.bizdate,b.closePrice FROM newzl.v_hsj_stock_hq_basic b WHERE b.bizdate>'2026-04-10' AND b.bizdate<='2026-04-13') b WHERE b.bizdate<='2026-04-13') t WHERE rn<=249;
